import django.db.models.deletion
import django.utils.timezone
import portal.events.models


TYPES = [("training", "Training"), ("competition", "Wettkampf"), ("course", "Lehrgang"), ("exam", "Prüfung"), ("other", "Sonstiges")]
# Name, Arten (leer: alle), Benutzerrollen, Team, abrechnungsrelevant, Rolle bei Anmeldung
ROLES = [
    ("Teilnehmer", [], [], False, False, True),
    ("Trainer", ["training", "course"], ["trainer"], True, True, False),
    ("Co-Trainer", ["training", "course"], ["trainer"], True, True, False),
    ("Prüfer", ["exam"], ["trainer"], True, False, False),
    ("Betreuer", ["competition", "course"], ["trainer"], True, False, False),
]


def forwards(apps, schema_editor):
    """Arten und Rollen anlegen; Anmeldungen und Begleitungen werden Teilnahmen (ADR 0012)."""
    from datetime import timedelta

    EventType = apps.get_model("events", "EventType")
    ParticipantRole = apps.get_model("events", "ParticipantRole")
    Event = apps.get_model("events", "Event")
    Occurrence = apps.get_model("events", "Occurrence")
    Participation = apps.get_model("events", "Participation")
    ScheduleTeam = apps.get_model("events", "ScheduleTeam")
    Registration = apps.get_model("events", "Registration")
    Staffing = apps.get_model("events", "Staffing")
    EventStaff = apps.get_model("events", "EventStaff")
    MemberLink = apps.get_model("members", "MemberLink")

    types = {}
    for order, (key, name) in enumerate(TYPES):
        types[key] = EventType.objects.create(name=name, order=order * 10)
    roles = {}
    for order, (name, kinds, user_roles, team, billable, default) in enumerate(ROLES):
        role = ParticipantRole.objects.create(
            name=name, order=order * 10, user_roles=user_roles, is_team=team, is_billable=billable, is_default=default
        )
        role.event_types.set([types[kind] for kind in kinds])
        roles[name] = role
    function_role = {"trainer": roles["Trainer"], "co_trainer": roles["Co-Trainer"]}

    for event in Event.objects.all():
        event.event_type = types.get(event.kind, types["other"])
        event.save(update_fields=["event_type"])
        for occurrence in Occurrence.objects.filter(event=event):
            if event.registration_opens_at:
                occurrence.registration_opens_at = event.registration_opens_at
            elif event.opens_days_before is not None:
                occurrence.registration_opens_at = occurrence.starts_at - timedelta(days=event.opens_days_before)
            if event.registration_closes_at:
                occurrence.registration_closes_at = event.registration_closes_at
            elif event.closes_hours_before is not None:
                occurrence.registration_closes_at = occurrence.starts_at - timedelta(hours=event.closes_hours_before)
            occurrence.save(update_fields=["registration_opens_at", "registration_closes_at"])
        for schedule in event.schedules.all():
            schedule.opens_hours_before = event.opens_days_before * 24 if event.opens_days_before is not None else None
            schedule.closes_hours_before = event.closes_hours_before
            schedule.save(update_fields=["opens_hours_before", "closes_hours_before"])

    for registration in Registration.objects.all():
        Participation.objects.create(
            occurrence_id=registration.occurrence_id,
            member_id=registration.member_id,
            role=roles["Teilnehmer"],
            status=registration.status,
            registered_by_id=registration.registered_by_id,
            exception_by_id=registration.exception_by_id,
            weight=registration.weight,
            note=registration.note,
            created_at=registration.created_at,
        )

    own = dict(MemberLink.objects.filter(kind="self").values_list("user_id", "member_id"))
    for staffing in Staffing.objects.all():
        member_id = own.get(staffing.user_id)
        if member_id is None:
            print(f"\n  Begleitung {staffing.pk} übersprungen: Benutzer {staffing.user_id} hat kein eigenes Mitgliedsprofil.")
            continue
        Participation.objects.update_or_create(
            occurrence_id=staffing.occurrence_id,
            member_id=member_id,
            defaults={
                "role": function_role[staffing.function],
                "status": "registered",
                "confirmed_at": staffing.confirmed_at,
                "minutes": staffing.minutes,
            },
        )
    for staff in EventStaff.objects.all():
        member_id = own.get(staff.user_id)
        if member_id is None:
            continue
        for schedule in staff.event.schedules.all():
            ScheduleTeam.objects.get_or_create(
                schedule=schedule, member_id=member_id, defaults={"role": function_role[staff.function]}
            )
